package ai.therahome.callwindow

import android.app.Activity
import android.app.PictureInPictureParams
import android.content.pm.PackageManager
import android.os.Build
import android.util.Rational

/**
 * The part of picture-in-picture that cannot live inside an Expo module.
 *
 * Two of the three things PiP needs are Activity callbacks, and MainActivity
 * is generated by `expo prebuild`, not written by us:
 *
 *   - `onUserLeaveHint()` is the ONLY place Android 8–11 accepts
 *     `enterPictureInPictureMode()` from. Called from `onPause` it is
 *     ignored, so a Home press on those versions has exactly one hook and
 *     this is it. Android 12 replaced it with `setAutoEnterEnabled`, which
 *     is smoother (no frame of the full-screen app on the way out), so
 *     from 31 up this deliberately does nothing and lets the system do it.
 *   - `onPictureInPictureModeChanged()` is how JavaScript learns it is now
 *     a 1-inch window and should draw the small call view instead of the
 *     whole app.
 *
 * So the overrides are injected into MainActivity by
 * `plugins/withAndroidPictureInPicture.js` and they call in here. This
 * object is the stable address they are written against: a plugin that
 * patches generated Kotlin should reference one name, not a moving module
 * instance.
 */
object CallWindow {
  /** True only while a call is actually running. Nothing else may put this
   * app in a PiP window — an app that shrinks itself when you press Home is
   * a bug, not a feature. */
  @Volatile
  var armed: Boolean = false

  /** Width ÷ height of the window to ask for. A video call gets its video's
   * shape; a voice call gets something closer to a bar, because that is all
   * a name and a timer need. Android clamps anything outside 1:2.39…2.39:1. */
  @Volatile
  var ratio: Double = 16.0 / 9.0

  @Volatile
  var inPip: Boolean = false

  /** Set by the module while it is alive; null once JS has gone away. */
  @Volatile
  var listener: ((Boolean) -> Unit)? = null

  /**
   * MainActivity → here, from `onUserLeaveHint`: Home or Recents.
   *
   * Does nothing on Android 12 and up, where `setAutoEnterEnabled` has
   * already put the app in its window — and done it better, without the
   * frame of full-screen app that entering by hand shows on the way out.
   */
  @JvmStatic
  fun onUserLeaving(activity: Activity) {
    if (!armed) return
    if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S) return
    enter(activity)
  }

  /**
   * MainActivity → here, from `invokeDefaultOnBackPressed`: Back on the
   * last screen, the other way out of the app.
   *
   * This one runs on every version, auto-enter or not. Back does not reach
   * `onUserLeaveHint` the way Home does — React Native answers it by moving
   * the task to the background, and `moveTaskToBack` is documented not to
   * call it — so without this, Back is the one exit that loses the call.
   *
   * Returns true when the app is now a window, which tells MainActivity to
   * swallow the Back rather than ALSO backgrounding the task: doing both
   * closes the window it just opened.
   */
  @JvmStatic
  fun onBackLeaving(activity: Activity): Boolean {
    if (!armed) return false
    return enter(activity)
  }

  /** MainActivity → here, then on to JavaScript. */
  @JvmStatic
  fun onModeChanged(inPictureInPicture: Boolean) {
    inPip = inPictureInPicture
    listener?.invoke(inPictureInPicture)
  }

  fun isSupported(activity: Activity?): Boolean {
    if (Build.VERSION.SDK_INT < Build.VERSION_CODES.O) return false
    val target = activity ?: return false
    return target.packageManager.hasSystemFeature(PackageManager.FEATURE_PICTURE_IN_PICTURE)
  }

  @android.annotation.TargetApi(Build.VERSION_CODES.O)
  fun params(): PictureInPictureParams {
    // Rational, not a float: Android's own type. A thousandth of a ratio is
    // far finer than any window it will actually draw.
    val builder = PictureInPictureParams.Builder()
      .setAspectRatio(Rational((ratio * 1000).toInt().coerceIn(420, 2380), 1000))
    if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S) {
      builder.setAutoEnterEnabled(armed)
      // Without this the window freezes on its last frame whenever the
      // layout changes size, which on a call is every time the timer ticks
      // from a narrow digit to a wide one.
      builder.setSeamlessResizeEnabled(true)
    }
    return builder.build()
  }

  /** Pushes the current `armed`/`ratio` at the system. On Android 12+ this
   * is what makes a Home press enter PiP by itself; below that it only
   * records the shape for the next `enter`. */
  @android.annotation.TargetApi(Build.VERSION_CODES.O)
  fun sync(activity: Activity?): Boolean {
    if (!isSupported(activity)) return false
    val target = activity ?: return false
    if (Build.VERSION.SDK_INT < Build.VERSION_CODES.S) return true
    return try {
      target.setPictureInPictureParams(params())
      true
    } catch (error: Throwable) {
      // A dying activity refuses this, and that is not worth a crash in the
      // middle of someone's call.
      false
    }
  }

  @android.annotation.TargetApi(Build.VERSION_CODES.O)
  fun enter(activity: Activity?): Boolean {
    if (!isSupported(activity)) return false
    val target = activity ?: return false
    if (target.isInPictureInPictureMode) return true
    return try {
      target.enterPictureInPictureMode(params())
    } catch (error: Throwable) {
      false
    }
  }

  /** Closes the window. There is no "leave PiP" API, so the task goes to
   * the back, which is what dismisses it — used when the call ends while
   * the user is in another app, so a finished call does not leave a dead
   * window floating over their screen. */
  fun exit(activity: Activity?): Boolean {
    val target = activity ?: return false
    if (!target.isInPictureInPictureMode) return false
    return try {
      target.moveTaskToBack(true)
    } catch (error: Throwable) {
      false
    }
  }
}
